}

{
  "presses": [
    "L-pinky-top",
    "L-ring-home",
    "L-middle-bottom",
    "L-middle-home"
  ],
  "locks": {
    "L-middle-bottom": "O",
    "L-middle-home": "A"
  },
  "note": "From T2/T3: L-middle-bottom=O (only in S2\\S3), L-middle-home=A (only in S3\\S2). Remaining {L-pinky-top,L-ring-home,R-index-home-in} = {C,J,W} unknown. This turn press {L-pinky-top,L-ring-home,L-middle-bottom(O),L-middle-home(A)} to learn which 2 of {C,J,W} are on {L-pinky-top,L-ring-home}; leftover letter gives R-index-home-in. Next: use chord with L-pinky-top+R-index-home-in (+O,+A) to separate C vs J vs W for each."
}

{
  "presses": ["L-ring-home", "L-pinky-home", "L-ring-top", "R-index-home-in"],
  "note": "Known: L-pinky-top=C; L-middle-home=A; L-middle-bottom=O; L-ring-home=J; R-index-home-in=W. Last rotation: L-index-top,R-ring-top (letters permuted there). This turn chord {L-ring-home,L-pinky-home,L-ring-top,R-index-home-in} => {J,W,x,y}; deduce {L-pinky-home,L-ring-top}={x,y} (which is which next via overlap with one of them + 2 known anchors)."
}

{
  "presses": ["L-ring-top", "L-ring-home", "R-index-home-in", "R-index-top-in"],
  "locks": {
    "L-ring-top": "E",
    "L-ring-home": "A",
    "R-index-home-in": "W"
